args.new_string:
norm = posixpath.normpath(path.replace("\\", "/"))
if not norm.startswith("public/") or "\x00" in path:
    raise HTTPException(403, "outside the public folder")

data_root = DATA.resolve()
public_root = data_root / "public"
try:
    target = (data_root / norm).resolve()
except (OSError, RuntimeError, ValueError):
    raise HTTPException(403, "cannot resolve the requested path")

if target == public_root or not target.is_relative_to(public_root):
    raise HTTPException(403, "outside the public folder")

try:
    if not target.is_file():
        raise HTTPException(404, "not found")
    return {"path": path, "content": target.read_text(encoding="utf-8")}
except FileNotFoundError:
    raise HTTPException(404, "not found")
